/**
 * Core Books Audit (2026-10-28): the DMG wondrous items missing from
 * the app, verified by a normalization pass over the SRD minor /
 * medium / major wondrous tables against ALL_MAGIC_ITEMS (the app
 * held only a fraction of the DMG list — e.g. only Type I of the Bag
 * of Holding and Necklace of Fireballs, and only the 1st-level Pearl
 * of Power). Prices are the SRD table values; summaries are headline
 * effects in our own words. Items already present under variant names
 * (Apparatus of Kwalish for the SRD's Apparatus of the Crab, Bead of
 * Force, Decanter of Endless Water, Portable Hole, and others) are
 * skipped.
 */
import type { MagicItemDefinition } from "@/engine/types";

type Row = [string, string, string, string, string?];

const SRC = "d20SRD — Magic Items: Wondrous Items";
const URL = "https://www.d20srd.org/srd/magicItems/wondrousItems.htm";

function build(rows: Row[]): MagicItemDefinition[] {
  return rows.map(([id, name, cost, summary, category]) => ({
    id,
    name,
    category: category ?? "wondrous",
    cost,
    summary,
    source: SRC,
    sourceUrl: URL,
    ruleset: "core" as const,
  }));
}

